<script setup lang="ts">
import type { ExportEntry, ExportJobState } from '~/types/exports'
import { exportLabels } from '~/utils/export-data'
defineProps<{ job: ExportJobState; entry?: ExportEntry | null; busy?: boolean; readError?: string; pause?: string }>()
defineEmits<{ download: [id: string]; refresh: [] }>()
</script>
<template><section class="export-job" :class="`export-job--${job.status}`" aria-labelledby="export-job-heading"><div class="export-status"><span aria-hidden="true">{{ job.status==='ready'?'✓':job.status==='failed'?'!':'⋯' }}</span><div><UiBadge :tone="job.status==='ready'?'success':job.status==='failed'?'warning':'neutral'">{{ job.status }}</UiBadge><h3 id="export-job-heading" aria-live="polite">{{ exportLabels[job.status] }}</h3><p v-if="job.status==='queued'">Задание принято в очередь. Обработка ещё не началась.</p><p v-else-if="job.status==='processing'">Сервер подготавливает документ. Процент готовности не сообщается.</p><p v-else-if="job.status==='ready'">Документ сформирован сервером. Допуск будет повторно проверен при скачивании.</p><p v-else>{{ job.error_message || 'Сервер не смог сформировать документ. Проверьте состояние и условия допуска.' }}</p></div></div><div v-if="job.status==='processing'" class="export-indeterminate" role="progressbar" aria-label="Подготовка документа без известного процента"><span /></div><p v-if="job.file_name" class="export-file-name">{{ job.file_name }}</p><UiAlert v-if="readError" tone="warning">Последнее действие не выполнено: {{ readError }}</UiAlert><p v-if="pause" role="status">{{ pause }}</p><p v-if="job.status==='ready' && !entry?.is_downloadable" class="text-warning">Скачивание сейчас недоступно по данным истории. Актуализируйте ревизию, источники и согласование.</p><div class="export-actions"><UiButton v-if="job.status==='ready'" :disabled="busy || !entry?.is_downloadable || !entry?.artifact" @click="$emit('download',job.id)"><img src="/icons/fe008/download.svg" width="17" height="17" alt="">Скачать документ</UiButton><UiButton variant="secondary" :disabled="busy" @click="$emit('refresh')">Обновить состояние</UiButton></div></section></template>
